    return heading('A library that works with you.','Collect your papers. Keep the evidence within reach.',btn('Import references','import-references','','references')+btn('Upload papers','upload','primary','plus'))+`<div class="upload-zone" id="dropzone"><div class="upload-icon">${icon('upload')}</div><div><h3>Bring your research together</h3><p>Choose a PDF to preview its local file metadata. No file is uploaded or processed.</p></div>${btn('Browse files','upload','','upload')}<input id="file-input" type="file" accept="application/pdf,.pdf" hidden multiple></div><div class="toolbar"><div class="row wrap"><div class="search box">${icon('search','sm')}<input id="library-search" aria-label="Search papers" placeholder="Search papers, authors, or year…" value="${esc(ui.query)}"></div><select id="library-filter" aria-label="Filter library">${['All papers','Ready','Processing','Failed','Local only',...state.projects.map(p=>p.id)].map(v=>`<option value="${v}" ${ui.filter===v?'selected':''}>${v.startsWith('p')?esc(project(v).title):v}</option>`).join('')}</select></div><div class="row gap8"><span class="muted tiny">${state.docs.length} papers</span><div class="view-toggle" role="group" aria-label="Library layout"><button class="${ui.view==='table'?'active':''}" data-view="table" aria-label="Table view" aria-pressed="${ui.view==='table'}">${icon('list','sm')}</button><button class="${ui.view==='grid'?'active':''}" data-view="grid" aria-label="Grid view" aria-pressed="${ui.view==='grid'}">${icon('grid','sm')}</button></div></div></div><div id="library-results">${libraryResults()}</div><div class="callout mt24">${icon('shield')}<p><strong>Source ownership is part of the design.</strong> In the application, project and document authorization must be verified before preview, retrieval, and download. This design export contains synthetic sources only.</p></div>`;
